<script setup lang="ts">
import {t} from './ui-language'
import {onMounted,ref,computed} from 'vue'
const props=defineProps<{busy:boolean}>()
const emit=defineEmits<{select:[value:{kind:string;item:any}]}>()
const items=ref<any[]>([]),error=ref(''),category=ref('ppt'),preview=ref<any>(null)
const dialog=ref<HTMLDialogElement>()
const categories=[['ppt','课件'],['script','讲稿'],['image','人像'],['audio','音频'],['topic','主题']]
const description=computed(()=>({ppt:'5 份可编辑 PPTX，每份 2 页，附配套逐页讲稿。',script:'5 份 DOCX 讲稿，使用“第1页”“第2页”对应课件。',image:'5 张 AI 生成的虚构讲师，均为 512×512 正方形 PNG。',audio:'5 段系统合成参考声音，支持试听；均为单声道 WAV。',topic:'5 个完整主题输入，包含教学对象、内容和目标语言。'}[category.value]))
function show(item:any){preview.value=item;dialog.value?.showModal()}
const imageFor=(item:any)=>category.value==='ppt'?item.slides[0]:category.value==='script'?item.scriptPreview:category.value==='image'?item.image:category.value==='audio'?item.audioPreview:item.slides[0]
const fileFor=(item:any)=>({ppt:item.ppt,script:item.script,image:item.image,audio:item.audio}[category.value]||'')
onMounted(async()=>{try{const response=await fetch('/examples/catalog.json');if(!response.ok)throw Error('示例材料暂时无法读取。');items.value=await response.json()}catch(e){error.value=(e as Error).message}})
</script>
<template>
 <section class="surface input-examples">
  <div class="eyebrow">EXAMPLE INPUTS</div><h2>{{t("每种输入都有 5 个示例")}}</h2><p class="examples-intro">{{t("先预览，再单独选用或整套填写。填写示例不会自动开始生成。")}}</p>
  <div class="example-tabs" :aria-label='t("示例材料类型")'><button v-for="[key,label] in categories" :key="key" :class="{chosen:category===key}" :aria-pressed="category===key" @click="category=key">{{t(label)}} <small>5</small></button></div>
  <p class="examples-description">{{t(description)}}</p><p v-if="error" class="error">{{t(error)}}</p>
  <div class="example-grid"><article v-for="(item,index) in items" :key="item.id" class="example-item">
   <button class="example-preview" :class="{portrait:category==='image',document:category==='script'}" :aria-label="t('预览')+item.name" @click="show(item)"><img :src="imageFor(item)" :alt="category==='image'?t('AI 生成的虚构讲师 ')+(index+1):item.name+t('示意图')" loading="lazy"><span>{{category==='image'?t("512×512 · AI 形象"):category==='script'?t("逐页讲稿 · DOCX"):category==='audio'?t("参考声音 · WAV"):category==='topic'?t("主题输入示例"):t("2 页 · PPTX")}}</span></button>
   <h3>{{category==='image'?t("虚构讲师 ")+(index+1):category==='audio'?t("示例声音 ")+(index+1):item.name}}</h3>
   <p class="example-language">{{item.languageLabel.split(' → ').map(t).join(' → ')}}</p><p v-if="category==='topic'" class="topic-snippet">{{item.topic}}</p>
   <audio v-if="category==='audio'" :src="item.audio" controls preload="none" :aria-label="t('试听示例声音')+(index+1)"></audio>
   <div class="example-links"><button @click="show(item)">{{t("预览")}}</button><a v-if="fileFor(item)" :href="fileFor(item)" download>{{t("下载")}}</a></div>
   <button class="secondary select-example" :disabled="props.busy" @click="emit('select',{kind:category,item})">{{props.busy?t("正在读取…"):t("选用此")+({ppt:t("课件"),script:t("讲稿"),image:t("人像"),audio:t("声音"),topic:t("主题")} as Record<string,string>)[category]}}</button>
   <button v-if="category==='ppt'||category==='script'||category==='topic'" class="text-button bundle-example" :disabled="props.busy" @click="emit('select',{kind:'bundle',item})">{{t("整套填入：课件＋讲稿＋人像＋声音")}}</button>
  </article></div>
  <p class="examples-note">{{t("示例讲稿与同名课件配套。虚构人像与系统合成音频可自由组合，不使用真实教师照片。")}}</p>
 </section>
 <dialog ref="dialog" class="example-dialog" @click="($event.target===dialog)&&dialog?.close()"><template v-if="preview"><header><strong>{{preview.name}} {{t("· 示例预览")}}</strong><button :aria-label='t("关闭预览")' @click="dialog?.close()">×</button></header><div class="example-dialog-body"><p>{{preview.languageLabel.split(' → ').map(t).join(' → ')}}</p><template v-if="category==='ppt'"><img v-for="url in preview.slides" :key="url" :src="url" :alt='t("示例课件页面")'></template><img v-else-if="category==='script'" :src="preview.scriptPreview" :alt='t("逐页讲稿预览")'><template v-else-if="category==='image'"><img class="dialog-portrait" :src="preview.image" :alt='t("AI 生成的虚构讲师")'><p>{{t("512×512 PNG · 正面、头部完整、浅色背景。")}}</p></template><template v-else-if="category==='audio'"><img :src="preview.audioPreview" :alt='t("参考音频波形")'><audio :src="preview.audio" controls preload="metadata"></audio><p>{{preview.voiceDurationSeconds}} {{t("秒 · 系统合成声音")}}</p></template><p v-else class="full-topic">{{preview.topic}}</p></div></template></dialog>
</template>
<style scoped>
.input-examples{padding:18px;margin-bottom:14px}.input-examples h2{font-size:18px;margin:7px 0}.examples-intro,.examples-description,.examples-note{font-size:12px;color:#74847c}.example-tabs{display:flex;gap:4px;margin:16px 0 12px;padding:4px;background:#f1f5f2;border-radius:10px}.example-tabs button{flex:1;min-width:0;padding:8px 2px;border-radius:7px;color:#7b8c81;background:none;font-size:12px;white-space:nowrap}.example-tabs button.chosen{background:#176b5b;color:white}.example-tabs small{font-size:9px;opacity:.75}.examples-description{min-height:40px}.example-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px;margin-top:12px}.example-item{padding:9px;border:1px solid #e0e9e3;border-radius:11px;min-width:0;background:#fcfdfc}.example-preview{display:block;position:relative;width:100%;aspect-ratio:16/10;padding:0;overflow:hidden;background:#edf4ef;border-radius:7px}.example-preview img{display:block;width:100%;height:100%;object-fit:contain}.example-preview.portrait{aspect-ratio:1}.example-preview.document{aspect-ratio:4/3}.example-preview.document img{object-fit:cover;object-position:top}.example-preview span{position:absolute;bottom:0;left:0;right:0;color:white;background:#173f32bd;padding:4px;font-size:9px;line-height:1.35}.example-item h3{font-size:12px;margin:9px 0 3px;overflow-wrap:anywhere}.example-language{font-size:10px;color:#51816b}.example-links{display:flex;justify-content:space-between;gap:7px;margin:8px 0}.example-links button,.example-links a{border:0;background:none;padding:0;font-size:11px;color:#4e7c64;text-decoration:none}.select-example{width:100%;font-size:11px;padding:8px 4px;min-height:35px}.bundle-example{font-size:10px;line-height:1.6;margin-top:5px;text-align:left}.example-item audio{width:100%;height:32px;margin-top:9px}.topic-snippet{font-size:10px;color:#78887e;line-height:1.7;margin-top:7px;display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical;overflow:hidden}.examples-note{margin-top:14px;line-height:1.75}.example-dialog{width:min(94vw,850px);max-height:88dvh;border:1px solid #dce7df;border-radius:14px;padding:0;color:#274b3c;overflow:auto}.example-dialog::backdrop{background:#0f211b80}.example-dialog header{position:sticky;top:0;display:flex;align-items:center;justify-content:space-between;background:white;padding:12px 16px;border-bottom:1px solid #e6eee8;z-index:1;font-size:13px}.example-dialog header button{background:none;font-size:28px;color:#557161}.example-dialog-body{padding:16px}.example-dialog-body>p{font-size:12px;margin-bottom:12px}.example-dialog-body img{display:block;width:100%;height:auto;margin-bottom:14px;border-radius:6px}.example-dialog-body img.dialog-portrait{max-width:512px;margin:0 auto 14px}.example-dialog-body audio{width:100%;margin-bottom:12px}.example-dialog-body .full-topic{font-size:16px;line-height:1.9}.example-grid>article:last-child:nth-child(odd){grid-column:1/-1;display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:0 12px}.example-grid>article:last-child:nth-child(odd) .example-preview{grid-row:1/6}.example-grid>article:last-child:nth-child(odd) audio{grid-column:2}
.example-tabs{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:5px}.example-tabs button{width:100%;padding:8px 4px}
</style>
